-- ============================================================================
-- ANC OVERALL SUMMARY - women with complete / missing mandatory and conditional fields
-- INPUT: a table or CTE named `mahis_pivot` (output of anc/mahis_anc_pivot.sql). To use a CTE instead of a table, put this script's
-- WITH list after `WITH RECURSIVE mahis_pivot AS ( <pivot query> ),`
-- Generated by build_dqa_scripts.py from the MNH Neonatal data dictionary rules.
-- ============================================================================
SET SESSION group_concat_max_len = 1000000;

WITH woman_level AS (
    -- One row per woman: latest non-empty value of each field across all visit days
    SELECT
        p.person_id,
        SUBSTRING_INDEX(GROUP_CONCAT(p.location_id ORDER BY p.visit_date DESC), ',', 1) AS location_id,
        MIN(p.visit_date) AS first_visit_date,
        MAX(p.visit_date) AS last_visit_date,
        COUNT(DISTINCT p.visit_date) AS number_of_visits,
        DATEDIFF(MAX(p.visit_date), MIN(p.visit_date)) + 1 AS days_spanned,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.sexually_transmitted_infection AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS sexually_transmitted_infection,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.dysmenorrhoea AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS dysmenorrhoea,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.folic_acid AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS folic_acid,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.albendazole AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS albendazole,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hepatitis_b AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hepatitis_b,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.sp AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS sp,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.condoms AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS condoms,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gait AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gait,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.parity AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS parity,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.respiratory_exam_findings AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS respiratory_exam_findings,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.muac AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS muac,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.drug_end_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS drug_end_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.contraceptive_use AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS contraceptive_use,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gravida AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gravida,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hiv_test_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hiv_test_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.side_effects AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS side_effects,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ipv_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ipv_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.random_blood_sugar AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS random_blood_sugar,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.lab_order_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS lab_order_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.tb_screening_result AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS tb_screening_result,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.past_surgeries AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS past_surgeries,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.genital_examination_normal AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS genital_examination_normal,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.symmetrical AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS symmetrical,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.vulva_inspection_abnormalities AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS vulva_inspection_abnormalities,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gestation_age_to_be_used AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gestation_age_to_be_used,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.the_woman_received_tetanus_doses_for_immunization AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS the_woman_received_tetanus_doses_for_immunization,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_tetanus_toxoid_tt_was_not_conducted AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_tetanus_toxoid_tt_was_not_conducted,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.daily_caffeine_use AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS daily_caffeine_use,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.which_medications_is_the_woman_currently_prescribed AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS which_medications_is_the_woman_currently_prescribed,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abortions_miscarriages AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abortions_miscarriages,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.stillbirths AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS stillbirths,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.live_births AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS live_births,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pregnancy_confirmed AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pregnancy_confirmed,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pregnancy_planned AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pregnancy_planned,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.iron_prescription AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS iron_prescription,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.iron_amount AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS iron_amount,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.type_of_iron_supplement_dosage AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS type_of_iron_supplement_dosage,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.amount_of_folic_acid AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS amount_of_folic_acid,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.iron_and_folic_acid_not_prescribed AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS iron_and_folic_acid_not_prescribed,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.vitamin_a_prescription AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS vitamin_a_prescription,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.vitamin_a_not_prescribed AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS vitamin_a_not_prescribed,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.aspirin_provided AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS aspirin_provided,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.intimateinfo AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS intimateinfo,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.additional_care_provided AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS additional_care_provided,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.safety_assessment AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS safety_assessment,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.physical_violence AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS physical_violence,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.violently_and_constantly_jealous AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS violently_and_constantly_jealous,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.antihelminthic_treatment AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS antihelminthic_treatment,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.no_preventative_treatment_provided AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS no_preventative_treatment_provided,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.counselling_on_diet AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS counselling_on_diet,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.livebirths AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS livebirths,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.lmnp_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS lmnp_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.tt1date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS tt1date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.tt2date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS tt2date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.perineal_tear AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS perineal_tear,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.evidence_of_amniotic_fluid AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS evidence_of_amniotic_fluid,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.symphysis_fundal_height AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS symphysis_fundal_height,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_fetuses_known AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_fetuses_known,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_fetuses AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_fetuses,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.repeated_fetal_rate AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS repeated_fetal_rate,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ultrasound_scan_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ultrasound_scan_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.tb_screening_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS tb_screening_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.medical_follow_up AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS medical_follow_up,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.persistent_symptom AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS persistent_symptom,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.misuse_of_drugs AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS misuse_of_drugs,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mode_of_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mode_of_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.past_pregnancies_complications AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS past_pregnancies_complications,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.best_verbal_response AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS best_verbal_response,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.eye_opening_response AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS eye_opening_response,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.best_motor_response AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS best_motor_response,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abnormal_bizzarre_behaviour AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abnormal_bizzarre_behaviour,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_tetanus_doses AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_tetanus_doses,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_pregnancy_outcome AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_pregnancy_outcome,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pregnancy_outcome_notes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pregnancy_outcome_notes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.preterm_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS preterm_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.age_at_menarche AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS age_at_menarche,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_behaviour_counselling_not_done AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_behaviour_counselling_not_done,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.behaviour_counselling AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS behaviour_counselling,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_any_diet_counselling_was_not_done AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_any_diet_counselling_was_not_done,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_clinical_counselling_not_done AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_clinical_counselling_not_done,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.clinical_counselling AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS clinical_counselling,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.danger_signs_present AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS danger_signs_present,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gestation_in_weeks AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gestation_in_weeks,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.vaginal_examination AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS vaginal_examination,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.insecticide_treated_net_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS insecticide_treated_net_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.comment_to_fulfiller AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS comment_to_fulfiller,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.regularity_of_menstrual_flow AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS regularity_of_menstrual_flow,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.amount_of_menstrual_flow AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS amount_of_menstrual_flow,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gynaecological_surgery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gynaecological_surgery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.tdv_at_gestation_age AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS tdv_at_gestation_age,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gestation_age_at_last_live_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gestation_age_at_last_live_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_aspirin_not_prescribed AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_aspirin_not_prescribed,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_sp_tablets_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_sp_tablets_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.folic_acid_not_prescribed AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS folic_acid_not_prescribed,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.vitamin_amount AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS vitamin_amount,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hepatitis_b_vaccine_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hepatitis_b_vaccine_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_hepatitis_b_vaccination_not_conducted AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_hepatitis_b_vaccination_not_conducted,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.preventive_counselling AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS preventive_counselling,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ultrasound_scan_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ultrasound_scan_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_ultrasound_not_done AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_ultrasound_not_done,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.location_of_the_placenta_detected_during_ultrasound AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS location_of_the_placenta_detected_during_ultrasound,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.urine_test_conducted AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS urine_test_conducted,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_urine_test_not_done AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_urine_test_not_done,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_tb_screening_not_done AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_tb_screening_not_done,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.urine_test_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS urine_test_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_for_test AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_for_test,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.arv_drugs_received AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS arv_drugs_received,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.amount_dispensed AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS amount_dispensed,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.diagnosis AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS diagnosis,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hiv_test AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hiv_test,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.co_trimoxazole_given_to_patient AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS co_trimoxazole_given_to_patient,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hiv_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hiv_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.systolic_blood_pressure AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS systolic_blood_pressure,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.diastolic_blood_pressure AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS diastolic_blood_pressure,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pulse AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pulse,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.temperature_c AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS temperature_c,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.weight_kg AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS weight_kg,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.height AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS height,
