        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.dead AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS dead,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.death_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS death_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.arv_number_identifier AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS arv_number_identifier,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_previous_pregnancy_groups AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_previous_pregnancy_groups,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_distinct_previous_pregnancies AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_distinct_previous_pregnancies,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.latest_previous_delivery_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS latest_previous_delivery_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_pregnancy_number AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_pregnancy_number,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_mode_of_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_mode_of_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_assisted_vaginal_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_assisted_vaginal_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_assisted_delivery_type AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_assisted_delivery_type,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_mode_of_delivery_details AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_mode_of_delivery_details,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_multiple_gestation AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_multiple_gestation,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_number_of_babies AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_number_of_babies,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_delivery_date_year AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_delivery_date_year,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_outcome_of_baby_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_outcome_of_baby_at_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_baby_birthweight AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_baby_birthweight,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_labour_duration_hours AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_labour_duration_hours,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_gestational_age_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_gestational_age_at_birth
    FROM mahis_pivot p
    GROUP BY p.person_id
),

rules AS (
    SELECT 'reason_for_visit' AS rule_id, 'anc_qc_reason_visit' AS dictionary_name, 'Reason the woman came to the facility today' AS label, 'Quick Check' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'previous_anc_visit' AS rule_id, 'anc_qc_previous_visit' AS dictionary_name, 'Any previous ANC visit/s at any facility?' AS label, 'Quick Check' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'pregnancy_confirmed' AS rule_id, 'anc_enrol_pregnancy_confirmed' AS dictionary_name, 'Is the pregnancy confirmed?' AS label, 'ANC Enrolment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'gestation_age_to_be_used' AS rule_id, 'anc_curr_preg_gestation_age_used' AS dictionary_name, 'Gestation age to be used' AS label, 'Current Pregnancy' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'lmnp_date' AS rule_id, 'anc_curr_preg_lmnp_date' AS dictionary_name, 'LNMP date' AS label, 'Current Pregnancy' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'ultrasound_scan_date' AS rule_id, 'anc_curr_preg_date' AS dictionary_name, 'Date for ultrasound' AS label, 'Current Pregnancy' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'gestation_weeks' AS rule_id, 'anc_curr_preg_gestation' AS dictionary_name, 'Gestation age by palpation (weeks)' AS label, 'Current Pregnancy' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'the_woman_received_tetanus_doses_for_immunization' AS rule_id, 'anc_curr_preg_received_tetanus_doses' AS dictionary_name, 'Woman received tetanus doses for immunization?' AS label, 'Current Pregnancy' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'tt1date' AS rule_id, 'anc_curr_preg_tt1_date' AS dictionary_name, 'TTV 1 immunisation date' AS label, 'Current Pregnancy' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'tt2date' AS rule_id, 'anc_curr_preg_tt2_date' AS dictionary_name, 'TTV 2 immunisation date' AS label, 'Current Pregnancy' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'gravida' AS rule_id, 'anc_ob_hist_gravida' AS dictionary_name, 'Gravida' AS label, 'Past Obstetric History' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'abortions_miscarriages' AS rule_id, 'anc_ob_hist_abortions_miscarriages' AS dictionary_name, 'Abortions/Miscarriages' AS label, 'Past Obstetric History' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'stillbirths' AS rule_id, 'anc_ob_hist_stillbirths' AS dictionary_name, 'Stillbirths' AS label, 'Past Obstetric History' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'past_pregnancies_complications' AS rule_id, 'anc_ob_hist_past_pregnancies_complic' AS dictionary_name, 'Complications during the past pregnancies?' AS label, 'Past Obstetric History' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'age_at_menarche' AS rule_id, 'anc_gynae_age_menarche' AS dictionary_name, 'Age at menarche' AS label, 'Gynaecological History' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'length_of_menstrual_flow' AS rule_id, 'anc_gynae_length_menstrual_flow_day' AS dictionary_name, 'Length of menstrual flow' AS label, 'Gynaecological History' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'regularity_of_menstrual_flow' AS rule_id, 'anc_gynae_regularity_menstrual_flow' AS dictionary_name, 'Regularity of menstrual flow' AS label, 'Gynaecological History' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'amount_of_menstrual_flow' AS rule_id, 'anc_gynae_amount_menstrual_flow' AS dictionary_name, 'Amount of menstrual flow' AS label, 'Gynaecological History' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'dysmenorrhoea' AS rule_id, 'anc_gynae_dysmenorrhea' AS dictionary_name, 'Dysmenorrhea' AS label, 'Gynaecological History' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'which_medications_is_the_woman_currently_prescribed' AS rule_id, 'anc_meds_medications_currently_presc' AS dictionary_name, 'Which medications is the woman currently prescribed?' AS label, 'Current Medications' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'daily_caffeine_use' AS rule_id, 'anc_behav_daily_caffeine_use' AS dictionary_name, 'Daily caffeine use' AS label, 'Behaviour & Lifestyle' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'misuse_of_drugs' AS rule_id, 'anc_behav_misuse_drugs' AS dictionary_name, 'Misuse of drugs' AS label, 'Behaviour & Lifestyle' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'height' AS rule_id, 'anc_vitals_height_cm' AS dictionary_name, 'Height' AS label, 'Vital Signs' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'weight_kg' AS rule_id, 'anc_vitals_weight' AS dictionary_name, 'Weight' AS label, 'Vital Signs' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'systolic_blood_pressure' AS rule_id, 'anc_vitals_systolic' AS dictionary_name, 'Systolic pressure' AS label, 'Vital Signs' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'diastolic_blood_pressure' AS rule_id, 'anc_vitals_diastolic' AS dictionary_name, 'Diastolic pressure' AS label, 'Vital Signs' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'pulse' AS rule_id, 'anc_vitals_pulse' AS dictionary_name, 'Pulse rate' AS label, 'Vital Signs' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'kempt' AS rule_id, 'anc_gen_exam_kempt' AS dictionary_name, 'Kempt' AS label, 'General Examination' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'gait' AS rule_id, 'anc_gen_exam_gait' AS dictionary_name, 'Gait' AS label, 'General Examination' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'nutritional_status' AS rule_id, 'anc_gen_exam_nutritional_status' AS dictionary_name, 'Nutritional status' AS label, 'General Examination' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'symphysis_fundal_height' AS rule_id, 'anc_abd_symphysis_fundal_height_sfh' AS dictionary_name, 'Symphysis-fundal height (SFH)' AS label, 'Abdominal & Fetal' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'antihelminthic_treatment' AS rule_id, 'anc_malaria_antihelminthic_treatment' AS dictionary_name, 'Was preventative antihelminthic treatment provided?' AS label, 'Deworming & Malaria' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'folic_acid' AS rule_id, 'anc_disp_folic_acid' AS dictionary_name, 'Daily dose of folic acid prescribed?' AS label, 'Medication Dispensed' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'anc_pregnancy_outcome' AS rule_id, 'anc_outcome_anc_pregnancy_outcome' AS dictionary_name, 'Outcome of the pregnancy' AS label, 'Pregnancy Outcome' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'pregnancy_planned' AS rule_id, 'anc_enrol_pregnancy_planned' AS dictionary_name, 'Was the pregnancy planned?' AS label, 'ANC Enrolment' AS section, 'CONDITIONAL' AS requirement, 'Pregnancy confirmed has a value' AS condition_text
    UNION ALL
    SELECT 'other_surgery_notes' AS rule_id, 'anc_med_hist_other_surgery_notes' AS dictionary_name, 'Specify other surgery' AS label, 'Medical History' AS section, 'CONDITIONAL' AS requirement, 'Past surgeries includes Other' AS condition_text
    UNION ALL
    SELECT 'other_allergy_notes' AS rule_id, 'anc_med_hist_other_allergy_notes' AS dictionary_name, 'Specify other allergy' AS label, 'Medical History' AS section, 'CONDITIONAL' AS requirement, 'Allergies includes Other' AS condition_text
    UNION ALL
    SELECT 'hiv_test_date' AS rule_id, 'anc_med_hist_hiv_test_date' AS dictionary_name, 'HIV test date' AS label, 'Medical History' AS section, 'CONDITIONAL' AS requirement, 'Chronic conditions includes HIV positive, or HIV status = Positive (the data records HIV in the HIV status field)' AS condition_text
    UNION ALL
    SELECT 'is_client_on_art' AS rule_id, 'anc_med_hist_client_art' AS dictionary_name, 'Is the client on ART?' AS label, 'Medical History' AS section, 'CONDITIONAL' AS requirement, 'Chronic conditions includes HIV positive, or HIV status = Positive (the data records HIV in the HIV status field)' AS condition_text
    UNION ALL
    SELECT 'art_number' AS rule_id, 'anc_med_hist_art_number' AS dictionary_name, 'ART number' AS label, 'Medical History' AS section, 'CONDITIONAL' AS requirement, 'Chronic conditions includes HIV positive, or HIV status = Positive (the data records HIV in the HIV status field)' AS condition_text
    UNION ALL
    SELECT 'albendazole' AS rule_id, 'anc_malaria_antihelminthic_treatment_' AS dictionary_name, 'Preventative antihelminthic treatment provided' AS label, 'Deworming & Malaria' AS section, 'CONDITIONAL' AS requirement, 'Antihelminthic treatment = Yes' AS condition_text
    UNION ALL
    SELECT 'no_preventative_treatment_provided' AS rule_id, 'anc_malaria_no_preventative_treatment' AS dictionary_name, 'Reason no preventative treatment provided' AS label, 'Deworming & Malaria' AS section, 'CONDITIONAL' AS requirement, 'Antihelminthic treatment = No' AS condition_text
    UNION ALL
    SELECT 'pregnancy_outcome_notes' AS rule_id, 'anc_outcome_pregnancy_outcome_not' AS dictionary_name, 'Outcome of the pregnancy - other (specify)' AS label, 'Pregnancy Outcome' AS section, 'CONDITIONAL' AS requirement, 'Pregnancy outcome = Other' AS condition_text
    UNION ALL
    SELECT 'estimated_date_of_delivery' AS rule_id, 'anc_outcome_estimated_date_delivery' AS dictionary_name, 'Estimated date of delivery' AS label, 'Pregnancy Outcome' AS section, 'CONDITIONAL' AS requirement, 'Pregnancy outcome = Live birth' AS condition_text
    UNION ALL
    SELECT 'place_of_delivery' AS rule_id, 'anc_outcome_place_delivery' AS dictionary_name, 'Place of delivery' AS label, 'Pregnancy Outcome' AS section, 'CONDITIONAL' AS requirement, 'Pregnancy outcome = Live birth' AS condition_text
    UNION ALL
    SELECT 'preterm_birth' AS rule_id, 'anc_outcome_preterm_birth' AS dictionary_name, 'Preterm birth' AS label, 'Pregnancy Outcome' AS section, 'CONDITIONAL' AS requirement, 'Pregnancy outcome = Live birth' AS condition_text
    UNION ALL
    SELECT 'mode_of_delivery' AS rule_id, 'anc_outcome_mode_delivery' AS dictionary_name, 'Mode of delivery' AS label, 'Pregnancy Outcome' AS section, 'CONDITIONAL' AS requirement, 'Pregnancy outcome = Live birth' AS condition_text
),

woman_rule_results AS (
    -- woman_level is read once: every rule result is packed as [applicable, present] in one JSON object per woman
    SELECT person_id, JSON_OBJECT(
        'reason_for_visit', JSON_ARRAY(1, CASE WHEN (reason_for_visit) IS NOT NULL THEN 1 ELSE 0 END),
        'previous_anc_visit', JSON_ARRAY(1, CASE WHEN (previous_anc_visit) IS NOT NULL THEN 1 ELSE 0 END),
        'pregnancy_confirmed', JSON_ARRAY(1, CASE WHEN (pregnancy_confirmed) IS NOT NULL THEN 1 ELSE 0 END),
        'gestation_age_to_be_used', JSON_ARRAY(1, CASE WHEN (gestation_age_to_be_used) IS NOT NULL THEN 1 ELSE 0 END),
        'lmnp_date', JSON_ARRAY(1, CASE WHEN (lmnp_date) IS NOT NULL THEN 1 ELSE 0 END),
        'ultrasound_scan_date', JSON_ARRAY(1, CASE WHEN (ultrasound_scan_date) IS NOT NULL THEN 1 ELSE 0 END),
        'gestation_weeks', JSON_ARRAY(1, CASE WHEN (COALESCE(gestation_weeks, gestation_in_weeks)) IS NOT NULL THEN 1 ELSE 0 END),
        'the_woman_received_tetanus_doses_for_immunization', JSON_ARRAY(1, CASE WHEN (the_woman_received_tetanus_doses_for_immunization) IS NOT NULL THEN 1 ELSE 0 END),
        'tt1date', JSON_ARRAY(1, CASE WHEN (tt1date) IS NOT NULL THEN 1 ELSE 0 END),
        'tt2date', JSON_ARRAY(1, CASE WHEN (tt2date) IS NOT NULL THEN 1 ELSE 0 END),
        'gravida', JSON_ARRAY(1, CASE WHEN (gravida) IS NOT NULL THEN 1 ELSE 0 END),
        'abortions_miscarriages', JSON_ARRAY(1, CASE WHEN (COALESCE(abortions_miscarriages, abortions)) IS NOT NULL THEN 1 ELSE 0 END),
        'stillbirths', JSON_ARRAY(1, CASE WHEN (stillbirths) IS NOT NULL THEN 1 ELSE 0 END),
        'past_pregnancies_complications', JSON_ARRAY(1, CASE WHEN (past_pregnancies_complications) IS NOT NULL THEN 1 ELSE 0 END),
        'age_at_menarche', JSON_ARRAY(1, CASE WHEN (age_at_menarche) IS NOT NULL THEN 1 ELSE 0 END),
        'length_of_menstrual_flow', JSON_ARRAY(1, CASE WHEN (length_of_menstrual_flow) IS NOT NULL THEN 1 ELSE 0 END),
        'regularity_of_menstrual_flow', JSON_ARRAY(1, CASE WHEN (regularity_of_menstrual_flow) IS NOT NULL THEN 1 ELSE 0 END),
        'amount_of_menstrual_flow', JSON_ARRAY(1, CASE WHEN (amount_of_menstrual_flow) IS NOT NULL THEN 1 ELSE 0 END),
        'dysmenorrhoea', JSON_ARRAY(1, CASE WHEN (dysmenorrhoea) IS NOT NULL THEN 1 ELSE 0 END),
        'which_medications_is_the_woman_currently_prescribed', JSON_ARRAY(1, CASE WHEN (which_medications_is_the_woman_currently_prescribed) IS NOT NULL THEN 1 ELSE 0 END),
        'daily_caffeine_use', JSON_ARRAY(1, CASE WHEN (daily_caffeine_use) IS NOT NULL THEN 1 ELSE 0 END),
        'misuse_of_drugs', JSON_ARRAY(1, CASE WHEN (misuse_of_drugs) IS NOT NULL THEN 1 ELSE 0 END),
        'height', JSON_ARRAY(1, CASE WHEN (height) IS NOT NULL THEN 1 ELSE 0 END),
        'weight_kg', JSON_ARRAY(1, CASE WHEN (weight_kg) IS NOT NULL THEN 1 ELSE 0 END),
        'systolic_blood_pressure', JSON_ARRAY(1, CASE WHEN (systolic_blood_pressure) IS NOT NULL THEN 1 ELSE 0 END),
        'diastolic_blood_pressure', JSON_ARRAY(1, CASE WHEN (diastolic_blood_pressure) IS NOT NULL THEN 1 ELSE 0 END),
        'pulse', JSON_ARRAY(1, CASE WHEN (pulse) IS NOT NULL THEN 1 ELSE 0 END),
        'kempt', JSON_ARRAY(1, CASE WHEN (kempt) IS NOT NULL THEN 1 ELSE 0 END),
        'gait', JSON_ARRAY(1, CASE WHEN (gait) IS NOT NULL THEN 1 ELSE 0 END),
        'nutritional_status', JSON_ARRAY(1, CASE WHEN (nutritional_status) IS NOT NULL THEN 1 ELSE 0 END),
        'symphysis_fundal_height', JSON_ARRAY(1, CASE WHEN (symphysis_fundal_height) IS NOT NULL THEN 1 ELSE 0 END),
        'antihelminthic_treatment', JSON_ARRAY(1, CASE WHEN (antihelminthic_treatment) IS NOT NULL THEN 1 ELSE 0 END),
        'folic_acid', JSON_ARRAY(1, CASE WHEN (folic_acid) IS NOT NULL THEN 1 ELSE 0 END),
        'anc_pregnancy_outcome', JSON_ARRAY(1, CASE WHEN (anc_pregnancy_outcome) IS NOT NULL THEN 1 ELSE 0 END),
        'pregnancy_planned', JSON_ARRAY(CASE WHEN COALESCE((pregnancy_confirmed IS NOT NULL), 0) THEN 1 ELSE 0 END, CASE WHEN (pregnancy_planned) IS NOT NULL THEN 1 ELSE 0 END),
        'other_surgery_notes', JSON_ARRAY(CASE WHEN COALESCE((LOWER(past_surgeries) LIKE '%other%'), 0) THEN 1 ELSE 0 END, CASE WHEN (other_surgery_notes) IS NOT NULL THEN 1 ELSE 0 END),
        'other_allergy_notes', JSON_ARRAY(CASE WHEN COALESCE((LOWER(allergies) LIKE '%other%'), 0) THEN 1 ELSE 0 END, CASE WHEN (other_allergy_notes) IS NOT NULL THEN 1 ELSE 0 END),
        'hiv_test_date', JSON_ARRAY(CASE WHEN COALESCE(((LOWER(chronic_conditions) LIKE '%hiv%' OR LOWER(hiv_status) = 'positive')), 0) THEN 1 ELSE 0 END, CASE WHEN (hiv_test_date) IS NOT NULL THEN 1 ELSE 0 END),
        'is_client_on_art', JSON_ARRAY(CASE WHEN COALESCE(((LOWER(chronic_conditions) LIKE '%hiv%' OR LOWER(hiv_status) = 'positive')), 0) THEN 1 ELSE 0 END, CASE WHEN (is_client_on_art) IS NOT NULL THEN 1 ELSE 0 END),
        'art_number', JSON_ARRAY(CASE WHEN COALESCE(((LOWER(chronic_conditions) LIKE '%hiv%' OR LOWER(hiv_status) = 'positive')), 0) THEN 1 ELSE 0 END, CASE WHEN (COALESCE(art_number, arv_number_identifier)) IS NOT NULL THEN 1 ELSE 0 END),
        'albendazole', JSON_ARRAY(CASE WHEN COALESCE((LOWER(antihelminthic_treatment) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (albendazole) IS NOT NULL THEN 1 ELSE 0 END),
        'no_preventative_treatment_provided', JSON_ARRAY(CASE WHEN COALESCE((LOWER(antihelminthic_treatment) = 'no'), 0) THEN 1 ELSE 0 END, CASE WHEN (no_preventative_treatment_provided) IS NOT NULL THEN 1 ELSE 0 END),
        'pregnancy_outcome_notes', JSON_ARRAY(CASE WHEN COALESCE((LOWER(anc_pregnancy_outcome) LIKE '%other%'), 0) THEN 1 ELSE 0 END, CASE WHEN (pregnancy_outcome_notes) IS NOT NULL THEN 1 ELSE 0 END),
        'estimated_date_of_delivery', JSON_ARRAY(CASE WHEN COALESCE((LOWER(anc_pregnancy_outcome) LIKE '%live birth%'), 0) THEN 1 ELSE 0 END, CASE WHEN (estimated_date_of_delivery) IS NOT NULL THEN 1 ELSE 0 END),
        'place_of_delivery', JSON_ARRAY(CASE WHEN COALESCE((LOWER(anc_pregnancy_outcome) LIKE '%live birth%'), 0) THEN 1 ELSE 0 END, CASE WHEN (place_of_delivery) IS NOT NULL THEN 1 ELSE 0 END),
        'preterm_birth', JSON_ARRAY(CASE WHEN COALESCE((LOWER(anc_pregnancy_outcome) LIKE '%live birth%'), 0) THEN 1 ELSE 0 END, CASE WHEN (preterm_birth) IS NOT NULL THEN 1 ELSE 0 END),
        'mode_of_delivery', JSON_ARRAY(CASE WHEN COALESCE((LOWER(anc_pregnancy_outcome) LIKE '%live birth%'), 0) THEN 1 ELSE 0 END, CASE WHEN (mode_of_delivery) IS NOT NULL THEN 1 ELSE 0 END)
    ) AS j
    FROM woman_level
),

field_status AS (
    -- Unpivot the JSON into one row per woman per rule
    SELECT
        b.person_id,
        k.rule_id,
        r.requirement,
        CAST(JSON_EXTRACT(b.j, CONCAT('$.', k.rule_id, '[0]')) AS UNSIGNED) AS applicable,
        CAST(JSON_EXTRACT(b.j, CONCAT('$.', k.rule_id, '[1]')) AS UNSIGNED) AS present
    FROM woman_rule_results b
    JOIN JSON_TABLE(JSON_KEYS(b.j), '$[*]' COLUMNS (rule_id VARCHAR(100) PATH '$')) k
    INNER JOIN rules r ON r.rule_id = k.rule_id
),

woman_dq AS (
    -- Per-woman counts of mandatory and conditional fields
    SELECT
        b.person_id,
        SUM(CASE WHEN f.requirement = 'MANDATORY' THEN 1 ELSE 0 END) AS mandatory_fields,
        SUM(CASE WHEN f.requirement = 'MANDATORY' AND f.present = 1 THEN 1 ELSE 0 END) AS mandatory_present,
        SUM(CASE WHEN f.requirement = 'MANDATORY' AND f.present = 0 THEN 1 ELSE 0 END) AS mandatory_missing,
        SUM(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 THEN 1 ELSE 0 END) AS conditional_required,
        SUM(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 AND f.present = 1 THEN 1 ELSE 0 END) AS conditional_present,
        SUM(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 AND f.present = 0 THEN 1 ELSE 0 END) AS conditional_missing,
        GROUP_CONCAT(CASE WHEN f.requirement = 'MANDATORY' AND f.present = 0 THEN f.rule_id END ORDER BY f.rule_id SEPARATOR '; ') AS missing_mandatory_fields,
        GROUP_CONCAT(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 AND f.present = 0 THEN f.rule_id END ORDER BY f.rule_id SEPARATOR '; ') AS missing_conditional_fields
    FROM woman_level b
    INNER JOIN field_status f ON f.person_id = b.person_id
    GROUP BY b.person_id
)

SELECT 'Total women' AS measure, COUNT(*) AS women, 100.0 AS pct FROM woman_dq
UNION ALL SELECT 'Women with ALL mandatory fields present', SUM(mandatory_missing = 0), ROUND(100 * SUM(mandatory_missing = 0) / COUNT(*), 1) FROM woman_dq
UNION ALL SELECT 'Women with MISSING mandatory fields', SUM(mandatory_missing > 0), ROUND(100 * SUM(mandatory_missing > 0) / COUNT(*), 1) FROM woman_dq
UNION ALL SELECT 'Women with required conditional fields missing', SUM(conditional_missing > 0), ROUND(100 * SUM(conditional_missing > 0) / COUNT(*), 1) FROM woman_dq
UNION ALL SELECT 'Women with all mandatory AND all required conditional fields present', SUM(mandatory_missing = 0 AND conditional_missing = 0), ROUND(100 * SUM(mandatory_missing = 0 AND conditional_missing = 0) / COUNT(*), 1) FROM woman_dq
UNION ALL SELECT 'Women with required conditional fields (any triggered)', SUM(conditional_required > 0), ROUND(100 * SUM(conditional_required > 0) / COUNT(*), 1) FROM woman_dq
UNION ALL SELECT 'Average mandatory completeness (% of mandatory fields present per woman)', COUNT(*), ROUND(AVG(100 * mandatory_present / mandatory_fields), 1) FROM woman_dq
UNION ALL SELECT 'Average required-conditional completeness (% present per woman)', SUM(conditional_required > 0), ROUND(AVG(CASE WHEN conditional_required > 0 THEN 100 * conditional_present / conditional_required END), 1) FROM woman_dq;
